#' Launch the locusmatch web application
#'
#' A three-step workflow:
#'
#' 1. **Earlier studies.** Pick the reference GWAS from Open Targets, either
#'    by trait (search, then choose among that trait's studies) or by pasting
#'    a list of accessions, narrow them down with filters (years, ancestry,
#'    study kind, number of cases) and tick or untick individual studies; or
#'    upload your own credible sets.
#' 2. **Your GWAS.** Upload its credible sets (optionally its thinned summary
#'    statistics), or pick one of the Open Targets studies as the query.
#' 3. **Results.** Interactive signal map, classification tables, downloads.
#'
#' Starts with the simulated [lm_example] data loaded, so every tab works
#' before anything is uploaded. *Load the schizophrenia example* shows the
#' bundled [lm_schizophrenia] analysis in one click. The logo in the menu bar
#' opens the home page.
#'
#' @param ... Passed to [shiny::shinyApp()] options, e.g. `port`.
#' @examples
#' if (interactive()) lm_app()
#' @export
lm_app <- function(...) {
  for (p in c("shiny", "bslib", "ggiraph", "DT")) {
    if (!requireNamespace(p, quietly = TRUE)) stop("install ", p, " to run the app")
  }
  shiny::shinyApp(app_ui(), app_server, options = list(...))
}

read_table_input <- function(f) {
  if (is.null(f)) return(NULL)
  data.table::fread(f$datapath)
}

parse_accessions <- function(text) {
  x <- unlist(strsplit(text %||% "", "[\\s,;]+", perl = TRUE))
  unique(x[nzchar(x)])
}

