# Logo, favicon and other static files: inst/www in the installed package; a
# www/ folder next to app.R in the browser (Shinylive) build.
lm_www_dir <- function() {
  # packageName() is NULL when this file is sourced outside the package (web build)
  pkg <- utils::packageName(environment(lm_www_dir))
  sf <- if (is.null(pkg)) "" else system.file("www", package = pkg)
  if (nzchar(sf)) sf else normalizePath("www", mustWork = FALSE)
}

