APP_HEAD_JS <- "
function locusmatchHome() {
  try {
    if (window.top !== window.self && typeof window.top.locusmatchShowLanding === 'function') {
      window.top.locusmatchShowLanding(); return;
    }
  } catch (e) {}
  Shiny.setInputValue('go_home', Date.now(), {priority: 'event'});
}

// Busy state while the signal map is computed and drawn: an overlay on the map
// and, for the example buttons, a spinner label. Cleared when the map arrives.
(function () {
  var timer = null;
  var EX = ['example_scz', 'example_home'];
  function setBusy(on, msg) {
    document.body.classList.toggle('lm-busy', on);
    var t = document.getElementById('lm-busy-text');
    if (t) t.textContent = msg || 'Drawing the signal map\u2026';
    EX.forEach(function (id) {
      var b = document.getElementById(id);
      if (!b) return;
      if (on) {
        if (!b.dataset.label) b.dataset.label = b.innerHTML;
        b.disabled = true;
        b.innerHTML = '<span class=\"spinner-border spinner-border-sm me-2\" aria-hidden=\"true\"></span>Loading\u2026';
      } else if (b.dataset.label) {
        b.disabled = false; b.innerHTML = b.dataset.label; delete b.dataset.label;
      }
    });
    clearTimeout(timer);
    if (on) timer = setTimeout(function () { setBusy(false); }, 180000);
  }
  window.locusmatchExampleBusy = function () { setBusy(true, 'Loading the schizophrenia example\u2026'); };
  document.addEventListener('click', function (e) {
    if (!e.target.closest) return;
    if (e.target.closest('#example_scz, #example_home')) window.locusmatchExampleBusy();
    else if (e.target.closest('#run')) setBusy(true, 'Comparing with earlier studies\u2026');
  }, true);
  document.addEventListener('DOMContentLoaded', function () {
    if (!window.jQuery) return;
    var $ = window.jQuery;
    $(document).on('shiny:recalculating', function (e) {
      if (e.target.id === 'map' && !document.body.classList.contains('lm-busy')) setBusy(true);
    });
    $(document).on('shiny:value shiny:error', function (e) {
      if (e.name === 'map') requestAnimationFrame(function () {
        requestAnimationFrame(function () { setBusy(false); });
      });
    });
  });
})();"

