marker_svg <- function(kind) {
  shape <- switch(kind,
    novel_locus = '<circle cx="7" cy="7" r="6" fill="#eb6834"/>',
    novel_signal = '<rect x="2.4" y="2.4" width="9.2" height="9.2" fill="#2a78d6" transform="rotate(45 7 7)"/>',
    replication = '<circle cx="7" cy="7" r="6" fill="#85837d"/>',
    ambiguous = '<circle cx="7" cy="7" r="5.2" fill="#fff" stroke="#52514e" stroke-width="1.6"/>')
  shiny::HTML(sprintf('<svg class="lm-mk" viewBox="0 0 14 14" aria-hidden="true">%s</svg>', shape))
}

# Reading guide shown above the signal map: a three-column strip, and the rest
# of the legend in a collapsible section right below it.
map_guide <- function() {
  shiny::div(
    class = "lm-guide-wrap",
    shiny::div(
      class = "lm-guide",
      shiny::div(shiny::tags$b("a. Signals of the study."), " One marker per fine-mapped signal, at its lead variant:",
                 marker_svg("novel_locus"), "novel locus,", marker_svg("novel_signal"), "new signal in a known locus,",
                 marker_svg("replication"), "known signal,", marker_svg("ambiguous"), "ambiguous.",
                 "Bigger markers are fine-mapped to fewer variants."),
      shiny::div(shiny::tags$b("b. Discovery history."), " One row per publication up to your study; a vertical",
                 "column of ticks is one signal reported again and again, and the dark tick marks who found it first."),
      shiny::div(shiny::tags$b("c. Cumulative discoveries."), " How many signals were known after each publication,",
                 "and how many it added. Hover over any mark for details.")
    ),
    shiny::tags$details(
      class = "lm-guide-more",
      shiny::tags$summary("More on reading the map"),
      shiny::markdown(MAP_GUIDE_MORE)
    )
  )
}

MAP_GUIDE_MORE <- "
* **Panel a.** Marker size is the posterior inclusion probability (PIP) of the top variant,
  so large markers are signals fine-mapped to few variants. The y-axis is square-root scaled
  so the many signals just past genome-wide significance stay legible; signals above the top
  of the axis are drawn at the cap with a small triangle. Grey dots underneath, when present,
  are your thinned summary statistics.
* **Panel b.** Publications are listed oldest first. Several accessions of one paper share a
  row, the smallest publications are pooled into one row labelled with their years, and other
  accessions of your study's own paper are left out (your study was not compared with them).
* **Panel c.** Only confirmed signals are counted. Your study's ambiguous signals are the
  outlined segment after the coloured ones and are not part of the *+n*.
* **Same signal or not.** Two credible sets are the same signal when their colocalisation
  posterior H4 passes the threshold (Bayes-factor colocalisation when both studies have log
  Bayes factors, the PIP-based approximation otherwise) or, with PIPs only, when most of their
  PIP mass is shared; they are distinct when H3 passes its threshold. Anything in between is
  *ambiguous*. Signal IDs (`<block>#<n>`) are tied to fixed LD blocks and never renamed.
* **Reference data.** Credible sets of earlier studies come from the Open Targets Platform:
  studies that only published top hits are fine-mapped there with PICS, studies with full
  summary statistics with SuSiE. Gene labels are Open Targets locus-to-gene predictions
  (score of at least 0.5).
"

