app_server <- function(input, output, session) {
  # `job` says what the signal map shows: the simulated demo at start-up, the
  # form of step 2 after "Compare", or the bundled schizophrenia example.
  rv <- shiny::reactiveValues(studies = NULL, ref = NULL, job = list(kind = "demo"))

  shiny::observeEvent(input$go_home, bslib::nav_select("navbar", "home", session = session))
  shiny::observeEvent(input$start_app, bslib::nav_select("navbar", "1. Earlier studies", session = session))

  # The website's landing page triggers the example with input$example_request.
  run_scz_example <- function() {
    ex <- lm_schizophrenia
    rv$ref <- list(cs = ex$cs, studies = ex$studies, cs_meta = ex$cs_meta)
    shiny::updateSelectInput(session, "query_study", selected = ex$query, choices = stats::setNames(
      ex$studies$study_id, ex$studies$label))
    shiny::updateRadioButtons(session, "query_mode", selected = "ot")
    shiny::updateSliderInput(session, "t_h4", value = ex$registry$params$t_h4)
    shiny::updateSliderInput(session, "t_h3", value = ex$registry$params$t_h3)
    rv$job <- list(kind = "schizophrenia", at = Sys.time())
    bslib::nav_select("navbar", "3. Signal map", session = session)
    shiny::showNotification(sprintf(
      "Schizophrenia example: %s against %d earlier primary GWAS (Open Targets %s snapshot).",
      ex$studies[study_id == ex$query]$label, match(ex$query, ex$studies$study_id) - 1L,
      ex$ot_release), duration = 8)
  }
  shiny::observeEvent(input$example_scz, run_scz_example())
  shiny::observeEvent(input$example_home, run_scz_example())
  shiny::observeEvent(input$example_request, run_scz_example())
  notify_error <- function(expr) tryCatch(expr, error = function(e) {
    shiny::showNotification(conditionMessage(e), type = "error", duration = 10)
    NULL
  })

  # ---- step 1: find and filter earlier studies --------------------------------
  shiny::observeEvent(input$trait_search, {
    hits <- notify_error(ot_search_traits(input$trait_text, n = 10))
    if (is.null(hits) || !nrow(hits)) return()
    hits <- hits[n_studies > 0]
    shiny::updateSelectInput(session, "trait_pick", selected = hits$trait_id[1], choices = stats::setNames(
      hits$trait_id, sprintf("%s (%s), %d GWAS", hits$name, hits$trait_id, hits$n_studies)))
  })

  shiny::observeEvent(input$list_studies, {
    st <- notify_error(shiny::withProgress(message = "Listing studies", {
      if (input$ref_mode == "trait") {
        shiny::validate(shiny::need(length(input$trait_pick), "Search and pick a trait first."))
        ot_studies(trait_ids = input$trait_pick, include_descendants = input$trait_descendants)
      } else {
        acc <- parse_accessions(input$accessions)
        shiny::validate(shiny::need(length(acc), "Paste at least one accession."))
        withCallingHandlers(ot_studies(accessions = acc), warning = function(w) {
          shiny::showNotification(conditionMessage(w), type = "warning", duration = 10)
          invokeRestart("muffleWarning")
        })
      }
    }))
    if (is.null(st)) return()
    rv$studies <- st
    yrs <- range(st$year, na.rm = TRUE)
    if (all(is.finite(yrs))) {
      shiny::updateSliderInput(session, "f_years", min = yrs[1], max = yrs[2], value = yrs)
    }
    pops <- sort(unique(unlist(strsplit(stats::na.omit(st$ancestries), ","))))
    shiny::updateCheckboxGroupInput(session, "f_ancestry", selected = character(),
                                    choices = stats::setNames(pops, ifelse(pops %in% names(ANCESTRY_LABELS),
                                                                           ANCESTRY_LABELS[pops], pops)))
    # accession lists are deliberate choices: do not filter them by kind
    if (input$ref_mode == "accession") {
      shiny::updateCheckboxGroupInput(session, "f_kinds", selected = names(KIND_LABELS))
    }
  })

  filtered <- shiny::reactive({
    shiny::req(rv$studies)
    lm_filter_studies(
      rv$studies, years = input$f_years,
      ancestry = if (length(input$f_ancestry)) input$f_ancestry,
      ancestry_match = input$f_anc_match, kinds = input$f_kinds,
      min_cases = if (isTRUE(input$f_min_cases > 0)) input$f_min_cases,
      min_n = if (isTRUE(input$f_min_n > 0)) input$f_min_n,
      require_credible_sets = input$f_need_cs
    )
  })

  output$study_status <- shiny::renderUI({
    if (input$ref_mode == "upload") {
      return(shiny::p("Upload credible sets and a study table, then press 'Use selected studies'."))
    }
    if (is.null(rv$studies)) {
      return(shiny::p("Search a trait or paste accessions, then press 'List studies'."))
    }
    shiny::span(class = "text-muted small", sprintf(
      "%d studies listed, %d pass the filters, %d selected. Click a row to leave it out or add it back.",
      nrow(rv$studies), nrow(filtered()), length(input$study_table_rows_selected)))
  })

  output$study_table <- DT::renderDT({
    f <- filtered()
    show <- f[, unname(STUDY_COLUMNS), with = FALSE]
    data.table::setnames(show, names(STUDY_COLUMNS))
    show[, Kind := KIND_SHORT[Kind]]
    show[, Ancestry := format_ancestry(Ancestry)]
    show[, Sumstats := data.table::fifelse(Sumstats, "yes", "no")]
    show[, Trait := ifelse(nchar(Trait) > 45, paste0(substr(Trait, 1, 44), "\u2026"), Trait)]
    show[, Accession := ifelse(grepl("^GCST", Accession),
      sprintf('<a href="https://www.ebi.ac.uk/gwas/studies/%s" target="_blank">%s</a>', Accession, Accession),
      Accession)]
    DT::datatable(show, escape = setdiff(names(show), "Accession"), rownames = FALSE,
                  class = "compact hover", selection = list(mode = "multiple", selected = seq_len(nrow(show))),
                  options = list(pageLength = 25, scrollX = TRUE, dom = "ftip",
                                 columnDefs = list(list(className = "dt-nowrap", targets = "_all"))))
  })
  table_proxy <- DT::dataTableProxy("study_table")
  shiny::observeEvent(input$sel_all, DT::selectRows(table_proxy, seq_len(nrow(filtered()))))
  shiny::observeEvent(input$sel_none, DT::selectRows(table_proxy, NULL))

  shiny::observeEvent(input$fetch, {
    if (input$ref_mode == "upload") {
      shiny::req(input$ref_cs, input$ref_studies)
      rv$ref <- notify_error(list(cs = lm_credible_sets(read_table_input(input$ref_cs)),
                                  studies = lm_studies(read_table_input(input$ref_studies)),
                                  cs_meta = NULL))
    } else {
      sel <- filtered()[input$study_table_rows_selected]
      if (!nrow(sel)) {
        shiny::showNotification("Select at least one study.", type = "warning")
        return()
      }
      rv$ref <- notify_error(shiny::withProgress(message = "Downloading credible sets", value = 0, {
        lm_reference_from_ot(sel, progress = function(done, total) shiny::setProgress(done / total))
      }))
    }
    if (!is.null(rv$ref)) {
      shiny::updateSelectInput(session, "query_study", choices = stats::setNames(
        rv$ref$studies$study_id, rv$ref$studies$label), selected = utils::tail(rv$ref$studies$study_id, 1))
      shiny::updateRadioButtons(session, "query_mode",
                                selected = if (input$ref_mode == "upload") "upload" else "ot")
      bslib::nav_select("navbar", "2. Your GWAS", session = session)
      shiny::showNotification(sprintf("Loaded %d credible sets from %d studies.",
                                      data.table::uniqueN(rv$ref$cs$cs_id), nrow(rv$ref$studies)))
    }
  })

  output$ref_summary <- shiny::renderUI({
    if (is.null(rv$ref)) return(shiny::p("No reference loaded yet: the demo uses simulated studies."))
    s <- rv$ref$studies
    methods <- if (!is.null(rv$ref$cs_meta)) rv$ref$cs_meta[, .N, by = method] else NULL
    shiny::tagList(
      shiny::p(sprintf("%d studies, %d credible sets, %s to %s.", nrow(s),
                       data.table::uniqueN(rv$ref$cs$cs_id), min(s$pub_date), max(s$pub_date))),
      if (!is.null(methods)) shiny::p(paste(sprintf("%s: %d", methods$method, methods$N), collapse = "; ")),
      if (!is.null(methods) && all(methods$method == "PICS")) shiny::p(class = "text-muted",
        "All credible sets come from reported top hits (PICS), so signals are compared through PIPs.")
    )
  })

  # ---- step 2-3: compare --------------------------------------------------------
  shiny::observeEvent(input$run, {
    rv$job <- list(kind = input$query_mode, t_h4 = input$t_h4, t_h3 = input$t_h3, at = Sys.time())
    bslib::nav_select("navbar", "3. Signal map", session = session)
  })

  inputs <- shiny::reactive({
    job <- rv$job
    shiny::isolate({
      if (job$kind == "demo") {
        ex <- lm_example
        return(list(cs = ex$cs, studies = ex$studies, sumstats = ex$sumstats,
                    blocks = lm_even_blocks(), reference_variants = ex$reference_variants,
                    query = ex$studies$study_id[nrow(ex$studies)], labels = NULL))
      }
      if (job$kind == "schizophrenia") {
        ex <- lm_schizophrenia
        return(list(cs = ex$cs, studies = ex$studies, sumstats = NULL, blocks = lm_even_blocks(),
                    reference_variants = NULL, query = ex$query,
                    labels = lm_labels_from_ot(ex$cs_meta), registry = ex$registry))
      }
      shiny::validate(shiny::need(rv$ref, "Load earlier studies in step 1 first."))
      blocks <- if (is.null(input$blocks)) lm_even_blocks() else lm_blocks(input$blocks$datapath)
      labels <- if (!is.null(rv$ref$cs_meta)) lm_labels_from_ot(rv$ref$cs_meta) else NULL
      sumstats <- read_table_input(input$query_sumstats)
      common <- list(sumstats = sumstats, blocks = blocks, reference_variants = NULL,
                     t_h4 = job$t_h4, t_h3 = job$t_h3)
      if (job$kind == "ot") {
        shiny::validate(shiny::need(input$query_study %in% rv$ref$cs$study_id,
                                    "The chosen study has no credible sets in the loaded reference."))
        return(c(list(cs = rv$ref$cs, studies = rv$ref$studies, query = input$query_study,
                      labels = labels), common))
      }
      shiny::validate(shiny::need(input$query_cs, "Upload your credible sets."))
      q <- read_table_input(input$query_cs)
      q[, `:=`(study_id = "query", cs_id = paste0("query:", cs_id))]
      if ("gene" %in% names(q)) {
        labels <- rbind(labels, unique(q[!is.na(gene) & gene != "", .(cs_id, label = gene)]))
      }
      studies <- rbind(rv$ref$studies, data.table::data.table(
        study_id = "query", pub_date = input$query_date, label = input$query_label), fill = TRUE)
      c(list(cs = rbind(rv$ref$cs, q, fill = TRUE), studies = studies, query = "query",
             labels = labels), common)
    })
  })

  reg <- shiny::reactive({
    x <- inputs()
    if (!is.null(x$registry)) return(x$registry)
    shiny::withProgress(message = "Colocalising credible sets", {
      lm_build_registry(x$cs, x$studies, x$blocks, t_h4 = x$t_h4 %||% 0.8, t_h3 = x$t_h3 %||% 0.8,
                        reference_variants = x$reference_variants)
    })
  })

  plot_args <- shiny::reactive(list(reg = reg(), query = inputs()$query,
                                    sumstats = inputs()$sumstats, labels = inputs()$labels,
                                    n_labels = 12))
  static_fig <- shiny::reactive(do.call(lm_plot_signal_map, plot_args()))

  output$summary <- shiny::renderUI({
    n <- reg()$calls[study_id == inputs()$query, .N, by = status]
    get <- function(s) if (s %in% n$status) n[status == s]$N else 0L
    shiny::p(shiny::HTML(sprintf(
      "<b>%d</b> signals: <b>%d</b> novel loci, <b>%d</b> new signals at known loci, <b>%d</b> known, <b>%d</b> ambiguous.",
      sum(n$N), get("novel_locus"), get("novel_signal"), get("replication"), get("ambiguous"))))
  })
  output$map <- ggiraph::renderGirafe(do.call(lm_plot_signal_map, c(plot_args(), interactive = TRUE)))
  calls_tab <- shiny::reactive({
    x <- reg()$calls[study_id == inputs()$query,
                     .(cs_id, signal_id, status, chrom, lead_pos, lead_variant, max_pip = round(max_pip, 3), n_variants,
                       lead_logp = round(lead_logp, 1), best_h4 = round(best_h4, 3), flags)]
    lab <- inputs()$labels
    if (!is.null(lab)) x <- merge(x, unique(lab, by = "cs_id")[, .(cs_id, gene = label)],
                                  by = "cs_id", all.x = TRUE)
    x
  })
  output$calls <- DT::renderDT(calls_tab(), rownames = FALSE,
                               options = list(pageLength = 15, scrollX = TRUE))
  output$signals <- DT::renderDT(reg()$signals, rownames = FALSE,
                                 options = list(pageLength = 15, scrollX = TRUE))

  save_fig <- function(device) function(file) {
    n_rows <- min(nrow(reg()$studies), 14)
    ggplot2::ggsave(file, static_fig(), width = 180, height = 70 + 3.2 * n_rows, units = "mm",
                    dpi = 300, device = device, bg = "white")
  }
  output$dl_png <- shiny::downloadHandler("locusmatch_signal_map.png", save_fig("png"))
  output$dl_svg <- shiny::downloadHandler("locusmatch_signal_map.svg", save_fig(svg_device))
  output$dl_pdf <- shiny::downloadHandler("locusmatch_signal_map.pdf", save_fig("pdf"))
  output$dl_calls <- shiny::downloadHandler("locusmatch_signals.tsv", function(file)
    data.table::fwrite(calls_tab(), file, sep = "\t"))
  output$dl_signals <- shiny::downloadHandler("locusmatch_registry.tsv", function(file)
    data.table::fwrite(reg()$signals, file, sep = "\t"))
}

/* locusmatch: guided tour shown on a first visit (no dependencies).
 *
 * locusmatchTour(true)            start the tour
 * locusmatchMaybeTour()           start it unless this browser has seen it
 * locusmatchMaybeTour({offerOnly: true})
 *                                 only offer it (small card), e.g. when the
 *                                 visitor opened the schizophrenia example
 *
 * Inside the website the landing page decides when to call these, because the
 * app loads hidden in the background; run on its own, the app calls
 * locusmatchMaybeTour() once Shiny has connected.
 */
(function () {
  var KEY = 'locusmatch.tour.v1';
  var STEPS = [
    { title: 'Welcome to locusmatch',
      text: 'A one-minute tour of how to find out which signals of a GWAS are new. You can skip it now and replay it any time from <b>Tour</b> in the menu.' },
    { tab: '1. Earlier studies', sel: '.lm-callout',
      title: 'Short on time?',
      text: 'Load the schizophrenia example to see a complete analysis of 36 published GWAS in one click.' },
    { tab: '1. Earlier studies', sel: '#ref_mode', up: '.shiny-input-container',
      title: 'Step 1: earlier studies',
      text: 'Choose how to find the studies you compare against: by trait, by a list of GWAS Catalog / FinnGen / UK Biobank accessions, or upload your own credible sets.' },
    { tab: '1. Earlier studies', sel: '#trait_text', up: '.d-flex',
      title: 'Search a trait',
      text: 'Type a trait and press <b>Search</b>, pick it from the list, then press <b>List studies</b>.' },
    { tab: '1. Earlier studies', sel: '#lm-filters-main',
      title: 'Filter the studies',
      text: 'Narrow the list by publication year and sample size (N); further down, by study kind, ancestry and number of cases. Only primary GWAS of the trait are kept by default.' },
    { tab: '1. Earlier studies', sel: '#fetch', up: '.d-flex',
      title: 'Pick and download',
      text: 'Every study that passes the filters is selected in the table: click a row to leave it out, then press <b>Use selected studies</b>.' },
    { tab: '2. Your GWAS', sel: '#query_mode', up: '.card',
      title: 'Step 2: your GWAS',
      text: 'Upload the credible sets of your GWAS, or pick one of the published studies, and press <b>Compare</b>. Uploaded files stay on your computer.' },
    { tab: '3. Signal map', sel: '.lm-guide',
      title: 'Step 3: the signal map',
      text: 'Each signal of your GWAS is labelled a novel locus, a new signal in a known locus or a known signal, next to the history of discovery of the trait. This strip explains the three panels, and <b>More on reading the map</b> opens the full legend; hover over the map for details.' },
    { tab: '3. Signal map', sel: '#dl_png', up: '.d-flex',
      title: 'Download the figure',
      text: 'Save the signal map as PNG (300 dpi), SVG (editable in Inkscape or Illustrator) or PDF.' },
    { sel: '.navbar a[data-value="Your signals"]',
      title: 'Tables',
      text: '<b>Your signals</b> lists every signal of your GWAS with its label; the <b>Signal registry</b> lists every signal across all studies. Both download as TSV.' },
    { sel: '#lm-tour-link',
      title: 'That is it',
      text: 'Replay this tour any time from here. The logo takes you back to the home page.' }
  ];

  var i = 0, nodes = null, startTab = null, active = false;

  function seen() { try { return localStorage.getItem(KEY) === 'done'; } catch (e) { return false; } }
  function markSeen() { try { localStorage.setItem(KEY, 'done'); } catch (e) {} }

  function css() {
    if (document.getElementById('lmt-css')) return;
    var st = document.createElement('style'); st.id = 'lmt-css';
    st.textContent =
      '.lmt-block{position:fixed;inset:0;z-index:2000;background:transparent}' +
      '.lmt-block.center{background:rgba(11,11,11,.5)}' +
      '.lmt-spot{position:fixed;z-index:2001;border-radius:10px;box-shadow:0 0 0 9999px rgba(11,11,11,.5);' +
        'pointer-events:none;transition:all .25s ease}' +
      '.lmt-pop{position:fixed;z-index:2002;width:min(340px,calc(100vw - 32px));background:#fff;color:#0b0b0b;' +
        'border-radius:12px;box-shadow:0 12px 40px rgba(0,0,0,.25);padding:16px 18px 12px;font:14px/1.5 system-ui,sans-serif}' +
      '.lmt-pop h4{margin:0 0 6px;font-size:15px;font-weight:650}' +
      '.lmt-pop p{margin:0 0 12px;color:#3d3c39}' +
      '.lmt-foot{display:flex;align-items:center;gap:8px}' +
      '.lmt-skip{margin-right:auto;background:none;border:0;color:#8a8984;padding:4px 0;cursor:pointer;font:inherit;text-decoration:underline}' +
      '.lmt-count{color:#8a8984;font-size:12px}' +
      '.lmt-btn{border-radius:999px;border:1px solid #c8cfd8;background:#fff;color:#17324d;padding:5px 14px;font:inherit;font-weight:600;cursor:pointer}' +
      '.lmt-btn.primary{background:#2a78d6;border-color:#2a78d6;color:#fff}' +
      '.lmt-offer{position:fixed;left:20px;bottom:20px;z-index:2002;width:min(320px,calc(100vw - 40px));background:#fff;' +
        'border:1px solid #e4e3df;border-radius:12px;box-shadow:0 10px 30px rgba(0,0,0,.15);padding:14px 16px;font:14px/1.5 system-ui,sans-serif}' +
      '.lmt-offer p{margin:0 0 10px}';
    document.head.appendChild(st);
  }

  function el(tag, cls, html) { var e = document.createElement(tag); if (cls) e.className = cls; if (html != null) e.innerHTML = html; return e; }

  function activeTab() {
    var a = document.querySelector('.navbar .nav-link.active[data-value]');
    return a ? a.getAttribute('data-value') : null;
  }
  function goTab(tab) {
    var a = document.querySelector('.navbar a.nav-link[data-value="' + tab + '"]');
    if (a && !a.classList.contains('active')) { a.click(); return true; }
    return false;
  }
  function target(step) {
    if (!step.sel) return null;
    var t = document.querySelector(step.sel);
    if (t && step.up && t.closest(step.up)) t = t.closest(step.up);
    if (!t) return null;
    var r = t.getBoundingClientRect();
    return (r.width > 0 && r.height > 0) ? t : null;
  }

  function place(t) {
    var pop = nodes.pop, spot = nodes.spot, pad = 6;
    var vw = window.innerWidth, vh = window.innerHeight;
    if (!t) {
      spot.style.display = 'none'; nodes.block.classList.add('center');
      pop.style.left = Math.max(16, (vw - pop.offsetWidth) / 2) + 'px';
      pop.style.top = Math.max(16, (vh - pop.offsetHeight) / 2) + 'px';
      return;
    }
    nodes.block.classList.remove('center');
    var r = t.getBoundingClientRect();
    spot.style.display = 'block';
    spot.style.left = (r.left - pad) + 'px'; spot.style.top = (r.top - pad) + 'px';
    spot.style.width = (r.width + 2 * pad) + 'px'; spot.style.height = (r.height + 2 * pad) + 'px';
    var ph = pop.offsetHeight, pw = pop.offsetWidth, top;
    if (r.bottom + 12 + ph < vh) top = r.bottom + 12;
    else if (r.top - 12 - ph > 0) top = r.top - 12 - ph;
    else top = Math.max(16, vh - ph - 16);
    var left = Math.min(Math.max(16, r.left), vw - pw - 16);
    pop.style.left = left + 'px'; pop.style.top = top + 'px';
  }

  function show(k, dir) {
    if (k < 0) k = 0;
    if (k >= STEPS.length) return finish();
    i = k;
    var step = STEPS[i];
    var switched = step.tab ? goTab(step.tab) : false;
    setTimeout(function () {
      var t = target(step);
      if (step.sel && !t) return show(i + (dir || 1), dir);   // element not on screen: skip the step
      if (t) t.scrollIntoView({ block: 'center', behavior: 'instant' in document.documentElement.style ? 'instant' : 'auto' });
      nodes.title.innerHTML = step.title;
      nodes.text.innerHTML = step.text;
      nodes.count.textContent = (i + 1) + ' / ' + STEPS.length;
      nodes.back.style.visibility = i === 0 ? 'hidden' : 'visible';
      nodes.next.textContent = i === 0 ? 'Start' : (i === STEPS.length - 1 ? 'Done' : 'Next');
      place(t);
      nodes.next.focus({ preventScroll: true });
    }, switched ? 350 : 30);
  }

  function onKey(e) {
    if (!active) return;
    if (e.key === 'Escape') finish();
    else if (e.key === 'ArrowRight') show(i + 1, 1);
    else if (e.key === 'ArrowLeft') show(i - 1, -1);
  }
  function onResize() { if (active) place(target(STEPS[i])); }

  function finish() {
    markSeen();
    active = false;
    if (nodes) { nodes.block.remove(); nodes.spot.remove(); nodes.pop.remove(); nodes = null; }
    document.removeEventListener('keydown', onKey);
    window.removeEventListener('resize', onResize);
    if (startTab) goTab(startTab);
  }

  function start() {
    if (active) return;
    removeOffer();
    css(); active = true; startTab = activeTab();
    nodes = { block: el('div', 'lmt-block'), spot: el('div', 'lmt-spot'), pop: el('div', 'lmt-pop') };
    nodes.pop.setAttribute('role', 'dialog'); nodes.pop.setAttribute('aria-live', 'polite');
    nodes.title = el('h4'); nodes.text = el('p');
    var foot = el('div', 'lmt-foot');
    var skip = el('button', 'lmt-skip', 'Skip tutorial'); skip.type = 'button'; skip.onclick = finish;
    nodes.count = el('span', 'lmt-count');
    nodes.back = el('button', 'lmt-btn', 'Back'); nodes.back.type = 'button'; nodes.back.onclick = function () { show(i - 1, -1); };
    nodes.next = el('button', 'lmt-btn primary', 'Next'); nodes.next.type = 'button'; nodes.next.onclick = function () { show(i + 1, 1); };
    foot.append(skip, nodes.count, nodes.back, nodes.next);
    nodes.pop.append(nodes.title, nodes.text, foot);
    document.body.append(nodes.block, nodes.spot, nodes.pop);
    document.addEventListener('keydown', onKey);
    window.addEventListener('resize', onResize);
    show(0, 1);
  }

  function removeOffer() { var o = document.querySelector('.lmt-offer'); if (o) o.remove(); }
  function offer() {
    if (document.querySelector('.lmt-offer')) return;
    css();
    var box = el('div', 'lmt-offer', '<p><b>First time here?</b> Take a one-minute tour of locusmatch.</p>');
    var foot = el('div', 'lmt-foot');
    var no = el('button', 'lmt-skip', 'No thanks'); no.type = 'button';
    no.onclick = function () { markSeen(); removeOffer(); };
    var yes = el('button', 'lmt-btn primary', 'Take the tour'); yes.type = 'button'; yes.onclick = start;
    foot.append(no, yes); box.append(foot);
    document.body.appendChild(box);
  }

  window.locusmatchTour = function () { start(); };
  window.locusmatchMaybeTour = function (opts) {
    if (seen() || active) return;
    if (opts && opts.offerOnly) offer(); else start();
  };

  function embeddedInLanding() {
    try { return window.top !== window.self && typeof window.top.locusmatchShowLanding === 'function'; }
    catch (e) { return false; }
  }
  // Run on its own (R or /app/ opened directly): offer the tour once Shiny is up.
  document.addEventListener('DOMContentLoaded', function () {
    if (!window.jQuery) return;
    window.jQuery(document).one('shiny:connected', function () {
      setTimeout(function () { if (!embeddedInLanding()) window.locusmatchMaybeTour(); }, 900);
    });
  });
})();
